<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {getAdminClubs} from '../../api/club'
import {createAdminUser,getAdminUsers,getRoles,updateAdminUser,updateAdminUserStatus} from '../../api/user'

const rows=ref([]),roles=ref([]),clubs=ref([]),total=ref(0),loading=ref(false),saving=ref(false),visible=ref(false),editingId=ref(null),formRef=ref()
const query=reactive({username:'',roleCode:'',userStatus:'',page:1,size:10})
const blank=()=>({username:'',phone:'',password:'',realName:'',roleCode:'USER',clubId:null,userStatus:'ENABLED'}),form=reactive(blank())
const roleName=(code)=>roles.value.find(r=>r.roleCode===code)?.roleName||code
const needsClub=computed(()=>form.roleCode==='CLUB')
const rules={username:[{required:true,message:'请输入用户名'},{min:4,max:50,message:'长度为4到50个字符'},{pattern:/^[A-Za-z0-9_]+$/,message:'只能使用字母、数字和下划线'}],phone:[{required:true,message:'请输入手机号'},{pattern:/^1\d{10}$/,message:'请输入11位手机号'}],password:[{validator:(_r,v,done)=>editingId.value||v?.length>=6?done():done(new Error('密码至少6位'))}],realName:[{required:true,message:'请输入姓名'}],roleCode:[{required:true,message:'请选择角色'}],clubId:[{validator:(_r,v,done)=>!needsClub.value||v?done():done(new Error('该角色必须绑定俱乐部'))}]}
const load=async()=>{loading.value=true;try{const d=(await getAdminUsers(query)).data;rows.value=d.records;total.value=d.total}finally{loading.value=false}}
const search=()=>{query.page=1;load()}
const open=row=>{editingId.value=row?.userId||null;Object.assign(form,blank(),row||{});form.password='';visible.value=true}
const save=async()=>{await formRef.value.validate();saving.value=true;try{const payload={realName:form.realName,phone:form.phone,roleCode:form.roleCode,clubId:needsClub.value?form.clubId:null,userStatus:form.userStatus};if(editingId.value)await updateAdminUser(editingId.value,payload);else await createAdminUser({...payload,username:form.username,password:form.password});visible.value=false;ElMessage.success('用户资料已保存');await load()}finally{saving.value=false}}
const toggle=async row=>{const enabling=row.userStatus!=='ENABLED';if(enabling&&row.roleCode==='CLUB'&&!row.clubId){ElMessage.warning('请先为该俱乐部负责人绑定俱乐部');return}await updateAdminUserStatus(row.userId,enabling?'ENABLED':'DISABLED');ElMessage.success('用户状态已更新');await load()}
onMounted(async()=>{const [r,c]=await Promise.all([getRoles(),getAdminClubs({page:1,size:100,status:'ACTIVE'})]);roles.value=r.data.filter(x=>x.roleStatus==='ENABLED');clubs.value=c.data.records;await load()})
</script>

<template><el-card><template #header><div class="head"><h2>用户管理</h2><el-button type="primary" @click="open()">新增用户</el-button></div></template><el-form inline><el-form-item label="用户名"><el-input v-model="query.username" clearable/></el-form-item><el-form-item label="角色"><el-select v-model="query.roleCode" clearable style="width:130px"><el-option v-for="r in roles" :key="r.roleCode" :label="r.roleName" :value="r.roleCode"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="query.userStatus" clearable style="width:120px"><el-option label="启用" value="ENABLED"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item><el-button type="primary" @click="search">查询</el-button></el-form><el-table :data="rows" v-loading="loading" empty-text="暂无用户"><el-table-column prop="username" label="用户名"/><el-table-column label="姓名/注册俱乐部名称" min-width="150"><template #default="{row}">{{row.realName}}</template></el-table-column><el-table-column prop="phone" label="手机号"/><el-table-column label="角色"><template #default="{row}">{{roleName(row.roleCode)}}</template></el-table-column><el-table-column label="当前绑定clubId"><template #default="{row}">{{row.clubId??'未绑定'}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><StatusTag :value="row.userStatus"/></template></el-table-column><el-table-column label="最后登录" min-width="150"><template #default="{row}">{{$formatDateTime(row.lastLoginAt)}}</template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link :type="row.userStatus==='ENABLED'?'danger':'success'" @click="toggle(row)">{{row.userStatus==='ENABLED'?'停用':'启用'}}</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.page" :page-size="query.size" :total="total" layout="total,prev,pager,next" @current-change="load"/></el-card><el-dialog v-model="visible" :title="editingId?'编辑用户':'新增用户'" width="560px"><el-form ref="formRef" :model="form" :rules="rules" label-width="90px"><el-form-item label="用户名" prop="username"><el-input v-model="form.username" :disabled="Boolean(editingId)"/></el-form-item><el-form-item v-if="!editingId" label="初始密码" prop="password"><el-input v-model="form.password" type="password" show-password/></el-form-item><el-form-item label="姓名" prop="realName"><el-input v-model="form.realName"/></el-form-item><el-form-item label="手机号" prop="phone"><el-input v-model="form.phone"/></el-form-item><el-form-item label="角色" prop="roleCode"><el-select v-model="form.roleCode"><el-option v-for="r in roles" :key="r.roleCode" :label="`${r.roleName}（${r.roleCode}）`" :value="r.roleCode"/></el-select></el-form-item><el-form-item v-if="needsClub" label="绑定俱乐部" prop="clubId"><el-select v-model="form.clubId" filterable><el-option v-for="c in clubs" :key="c.clubId" :label="c.clubName" :value="c.clubId"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="form.userStatus"><el-option label="启用" value="ENABLED"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></template>
<style scoped>.head{display:flex;align-items:center;justify-content:space-between}.head h2{margin:0}.el-pagination{margin-top:16px;justify-content:flex-end}</style>
